{"requirements": [
    {
        "id": 1,
        "text": "The system shall complete 33 levels successfully."
    },
    {
        "id": 2,
        "text": "The system shall display a board that is 200 pixels wide horizontally and 300 pixels wide vertically."
    },
    {
        "id": 3,
        "text": "The system shall display rectangular blocks with a width of 20 pixels and height of 10 pixels for bricks and a diameter of 10 pixels for the ball."
    },
    {
        "id": 4,
        "text": "The system shall start each level with the ball at the top left corner of the board, moving downwards with a straight trajectory at a 45° angle and a speed of 5 pixels per second."
    },
    {
        "id": 5,
        "text": "The system shall allow the user to move a paddle to hit the ball, changing its direction upward."
    },
    {
        "id": 6,
        "text": "The system shall allow the user to successfully complete a level by breaking all bricks."
    },
    {
        "id": 7,
        "text": "The system shall display bricks with a color (blue, red, gold) and size (single or double)."
    },
    {
        "id": 8,
        "text": "The system shall display bricks with a size of 20 x 10 pixels for single bricks and 60 x 10 pixels for double bricks."
    },
    {
        "id": 9,
        "text": "The system shall destroy blue bricks with one hit, red bricks with two hits, and gold bricks with three hits."
    },
    {
        "id": 10,
        "text": "The system shall initialize the first level with 50 blue, single bricks placed in the brick section of the board."
    },
    {
        "id": 11,
        "text": "The system shall allow the user to move the paddle horizontally on the bottom of the board, controlled by the left and right arrow keys."
    },
    {
        "id": 12,
        "text": "The system shall change the ball direction every time the ball hits the paddle or the border of the board (except for the bottom border) with the correct angle of reflection."
    },
    {
        "id": 13,
        "text": "The system shall increase the speed of the ball by a sufficient amount every time the next level starts."
    },
    {
        "id": 14,
        "text": "The system shall remove two red bricks and one gold brick from the brick arrangement and increase the difficulty every time the user finishes a level."
    },
    {
        "id": 15,
        "text": "The system shall generate a random brick pattern and arrangement for each level."
    },
    {
        "id": 16,
        "text": "The system shall provide the user with 3 lives."
    },
    {
        "id": 17,
        "text": "The system shall deduct one life from the user every time the ball falls off the side of the board."
    },
    {
        "id": 18,
        "text": "The system shall restart the level if the user loses a life but still has lives remaining. The system shall end the game if the user loses all lives."
    },
    {
        "id": 19,
        "text": "The system shall allow the user to start a new game from level 1 or end the game when it is over."
    }
]}
